function lockLearnerApis(){for(const key of ['indexedDB','caches','fetch','XMLHttpRequest','WebSocket','EventSource','WebTransport','Worker','SharedWorker','BroadcastChannel','importScripts','postMessage']){let o=self;while(o){try{const d=Object.getOwnPropertyDescriptor(o,key);if(d?.configurable)delete o[key]}catch{}o=Object.getPrototypeOf(o)}try{Object.defineProperty(self,key,{value:undefined,writable:false,configurable:false})}catch{}}}

/* Actual synchronous JavaScript. input() is a Nunya teaching helper, not a JS built-in. */
const send=self.postMessage.bind(self);
function same(a,b,tolerance=0){if(typeof b==='number')return typeof a==='number'&&Number.isFinite(a)&&Math.abs(a-b)<=tolerance;if(b===null||typeof b!=='object')return a===b;if(Array.isArray(a)!==Array.isArray(b)||!a||Object.keys(a).length!==Object.keys(b).length)return false;return Object.keys(b).every(k=>Object.hasOwn(a,k)&&same(a[k],b[k],tolerance))}
self.onmessage=({data})=>{send({ready:true});lockLearnerApis();try{if(typeof data.code!=='string'||data.code.length>12000)throw Error('Programme trop long.');const results=[];for(const test of data.tests){let output='',index=0;const console={log:(...args)=>{const line=args.map(a=>typeof a==='string'?a:JSON.stringify(a)).join(' ');if(output.length+line.length>16000)throw RangeError('La console dépasse 16 000 caractères.');output+=line+'\n'}};try{const input=()=>{if(index>=test.inputs.length)throw RangeError('Le programme demande plus de saisies que prévu.');return String(test.inputs[index++])};const read=new Function('console','input',data.code+'\n;return name=>eval(name);')(console,input),checks=[];for(const assertion of test.calls||[]){if(!/^[A-Za-z_$][\w$]*$/.test(assertion.name))throw Error('Nom de vérification invalide.');const target=read(assertion.name),args=structuredClone(assertion.args||[]),before=structuredClone(args),actual=typeof target==='function'?target(...args):target;checks.push({name:assertion.name,passed:same(actual,assertion.expected,assertion.tolerance||0)&&(!assertion.unchanged_args||same(args,before)),actual:JSON.stringify(actual)?.slice(0,500)||String(actual),expected:JSON.stringify(assertion.expected)})}results.push({output,checks,assertions_passed:checks.every(c=>c.passed)})}catch(error){results.push({output,error:error.name,detail:error.message})}}send({done:true,results,constructs_passed:true})}catch(error){send({error:error.message})}};
